**js/app.js**
```js
let cart = [
  { id: 1, name: 'Canvas Sneaker', price: 79, qty: 1 },
  { id: 2, name: 'Wool Beanie', price: 24, qty: 2 }
];
const items = document.getElementById('items');
const totalEl = document.getElementById('total');

function render() {
  items.innerHTML = cart.map(i => `
    <div class='item' data-id='${i.id}'>
      <h3>${i.name}</h3>
      <div class='qty'>
        <button data-act='minus' aria-label='Decrease'>-</button>
        <span>${i.qty}</span>
        <button data-act='plus' aria-label='Increase'>+</button>
      </div>
      <span>$${(i.price * i.qty).toFixed(2)}</span>
      <button class='remove' data-act='remove'>Remove</button>
    </div>`).join('');
  const total = cart.reduce((s, i) => s + i.price * i.qty, 0);
  totalEl.textContent = '$' + total.toFixed(2);
}

items.addEventListener('click', e => {
  const btn = e.target.closest('button');
  if (!btn) return;
  const id = Number(btn.closest('.item').dataset.id);
  const line = cart.find(i => i.id === id);
  if (btn.dataset.act === 'plus') line.qty++;
  if (btn.dataset.act === 'minus') line.qty = Math.max(1, line.qty - 1);
  if (btn.dataset.act === 'remove') cart = cart.filter(i => i.id !== id);
  render();
});
render();
```

Why it works: one delegated click listener handles every button through data-act attributes, state lives in a single array, and render() is the only function that touches the DOM — so the total can never drift out of sync.

```js
// Object destructuring
const user = { id: 7, name: 'Sara', address: { city: 'Tehran', zip: '12345' } };
const { name, id, role = 'guest', city } = { ...user, ...user.address }; // role default + nested city
console.log(name, id, role, city); // Sara 7 guest Tehran

// Renaming
const { name: fullName } = user;
console.log(fullName); // Sara

// Array destructuring
const rgb = [255, 128, 0];
const [r, g, b] = rgb;
const [first, , third] = rgb;             // skip items
const [head = 0, ...tail] = rgb;          // rest elements
console.log(r, g, b, first, third, tail); // 255 128 0 255 0 [128, 0]

// Swapping without a temp variable
let x = 1, y = 2;
[x, y] = [y, x];

// Function parameter destructuring (common for options objects)
function draw({ x = 0, y = 0, color = 'black' } = {}) {
  return `circle at ${x},${y} in ${color}`;
}
console.log(draw({ x: 10 })); // circle at 10,0 in black
```
Destructuring pulls values out of arrays/objects into variables in one step. Patterns work at any depth, support defaults, renaming (`{ a: alias }`), rest elements, and defaulting the whole parameter with `= {}` so the function stays callable with no arguments.
